"""Build a local, paginated browser for the collected source-caption references."""
import argparse,csv,json
from pathlib import Path


def build(root):
 root=Path(root);rows=[json.loads(line) for line in (root/'总清单.jsonl').read_text().splitlines() if line.strip()]
 supplemental=root/'精选补充/总清单.jsonl'
 if supplemental.exists():rows.extend(json.loads(line) for line in supplemental.read_text().splitlines() if line.strip())
 fields=['industry_id','category','file','caption','caption_file','metadata_file','source_page','original_url','saved_kind','width','height','sha256','label_status','license_status']
 with (root/('总清单_含精选.csv' if supplemental.exists() else '总清单.csv')).open('w',encoding='utf-8-sig',newline='') as f:
  writer=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');writer.writeheader();writer.writerows(rows)
 data=json.dumps([{k:r.get(k) for k in ['id','industry_id','category_id','category','caption','file','caption_file','metadata_file','source_page','saved_kind','width','height','collection_track','selection_reason']} for r in rows],ensure_ascii=False).replace('<','\\u003c')
 page=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>制造能源工业图文资料</title><style>body{margin:0;background:#f4f7fc;color:#17243b;font:14px system-ui,sans-serif}header{padding:22px 4vw;background:white;border-bottom:1px solid #dce5f3;position:sticky;top:0;z-index:2}h1{font-size:23px;margin:0 0 8px}p{color:#62728b;line-height:1.6}nav{display:flex;gap:10px;flex-wrap:wrap;align-items:center}select,input,button{font:inherit;border:1px solid #cfdaeb;border-radius:7px;padding:8px;background:#fff;color:#203755}input{min-width:180px}button{cursor:pointer}button:disabled{opacity:.4}main{padding:22px 4vw;display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:18px}article{background:white;border:1px solid #dce5f3;border-radius:12px;overflow:hidden}article img{display:block;width:100%;height:200px;object-fit:contain;background:#edf2f8}.info{padding:13px}.caption{color:#20324b;margin:8px 0;overflow-wrap:anywhere}.links{display:flex;gap:12px;flex-wrap:wrap}a{color:#2463cb}small{color:#62728b}</style><header><h1>制造能源工业图文资料</h1><p>六个行业 · 每张配原始介绍与来源记录 · 网页标签待审核，原图和预览图分别标记</p><nav><select id="industry"><option value="">全部行业</option></select><select id="category"><option value="">全部搜索分类</option></select><input id="query" aria-label="搜索图片介绍" placeholder="搜索原始介绍"><button id="prev">上一页</button><span id="count"></span><button id="next">下一页</button></nav></header><main id="grid"></main><script>const rows=DATA,labels={automotive:'汽车制造',high_end_equipment:'高端装备',electronics:'电子制造',consumer_goods:'消费品制造',materials:'材料',energy:'能源'},industry=document.querySelector('#industry'),category=document.querySelector('#category'),query=document.querySelector('#query'),grid=document.querySelector('#grid');let page=0;for(const [id,name] of Object.entries(labels)){let o=document.createElement('option');o.value=id;o.textContent=name;industry.append(o)}function categories(){category.replaceChildren(new Option('全部搜索分类',''));const names=new Map(rows.filter(r=>!industry.value||r.industry_id===industry.value).map(r=>[r.category_id,r.category]));for(const [id,name] of names)category.append(new Option(name,id))}function render(){const selected=rows.filter(r=>(!industry.value||r.industry_id===industry.value)&&(!category.value||r.category_id===category.value)&&r.caption.toLocaleLowerCase().includes(query.value.toLocaleLowerCase()));const pages=Math.max(1,Math.ceil(selected.length/50));page=Math.max(0,Math.min(page,pages-1));grid.replaceChildren();document.querySelector('#count').textContent=`${selected.length} 张 · ${page+1} / ${pages}`;document.querySelector('#prev').disabled=page===0;document.querySelector('#next').disabled=page+1>=pages;for(const r of selected.slice(page*50,page*50+50)){const card=document.createElement('article'),a=document.createElement('a'),image=document.createElement('img'),info=document.createElement('div'),caption=document.createElement('p'),small=document.createElement('small'),links=document.createElement('div');a.href=r.file;a.target='_blank';image.src=r.file;image.alt=r.caption;image.loading='lazy';a.append(image);info.className='info';caption.className='caption';caption.textContent=r.caption;small.textContent=`${labels[r.industry_id]} / ${r.category} · ${r.width}×${r.height} · ${r.saved_kind==='source_image'?'源站图片':'Google预览图'}${r.collection_track==='curated_supplement'?' · 精选补充':''}`;links.className='links';for(const [name,url] of [['介绍TXT',r.caption_file],['来源JSON',r.metadata_file],['来源网页',r.source_page]]){if(!url)continue;if(name==='来源网页'&&!/^https?:\/\//.test(url))continue;let link=document.createElement('a');link.href=url;link.textContent=name;link.target='_blank';link.rel='noopener noreferrer';links.append(link)}info.append(small,caption,links);card.append(a,info);grid.append(card)}}industry.onchange=()=>{page=0;categories();render()};category.onchange=query.oninput=()=>{page=0;render()};document.querySelector('#prev').onclick=()=>{page--;render()};document.querySelector('#next').onclick=()=>{page++;render()};categories();render();</script></html>'''.replace('DATA',data)
 reviewed=root/'筛选结果.json'
 if reviewed.exists():
  report=json.loads(reviewed.read_text())
  page=page.replace('六个行业 · 每张配原始介绍与来源记录 · 网页标签待审核，原图和预览图分别标记',f'材料与能源 · 流程制造相关参考 · 核心 {report["core_images"]} 张 / 补充 {report["supplement_images"]} 张。已做画面相关性筛选；来源介绍和技术事实仍待核验。')
  page=page.replace("r.collection_track==='curated_supplement'?' · 精选补充':''", "r.collection_track==='process_core'?' · 核心流程参考':r.collection_track==='process_supplement'?' · 补充流程参考':r.collection_track==='curated_supplement'?' · 精选补充':''")
  page=page.replace("info.append(small,caption,links)","const review=document.createElement('p');review.className='review';review.textContent=r.selection_reason||'';info.append(small,caption,review,links)")
 else:
  page=page.replace('六个行业 · 每张配原始介绍与来源记录 · 网页标签待审核，原图和预览图分别标记','历史宽泛候选包 · 汽车/高端装备/电子按原搜索标签收集；消费品宏观图和宽泛材料另保留。未做全量看图筛选，不等于合格工艺知识。')
 (root/'图片浏览.html').write_text(page,encoding='utf-8');return len(rows)

if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,default=Path(__file__).resolve().parents[1]/'data/runtime/industry-images-20261102-v1');args=p.parse_args();print(json.dumps({'gallery_images':build(args.output),'path':str(args.output/'图片浏览.html')},ensure_ascii=False))
